const fs = require('fs-extra');
const path = require('path');

var _robloxPathDict;
var _options

var luaTypes = {}
var serviceCollectionExtensions = {}

var parseLuaType = require('./parse-lua-types')


function genModule(filePath) {


    filePath = filePath.replace(/\\/g, '/');


    const luaContent = fs.readFileSync(filePath, 'utf8');
    var rbxPath = _robloxPathDict.getRbxPath(filePath)
    var ctorInfo = parseLuaType(luaContent)

    if (!ctorInfo) {
        return false
    }


    luaTypes[rbxPath] = {
        FilePath: filePath,
        Parameters: ctorInfo.Params
    };

    if (ctorInfo.CtorName != null) {
        luaTypes[rbxPath]["Ctor"] = ctorInfo.CtorName
    }

    return true
}


function tryGenHostBuilderExtension(filePath) {
    if (!isServiceFile(filePath)) {
        return false
    }

    var isDir = fs.statSync(filePath).isDirectory()
    var rbxPath = ""
    var name = ""
    if (isDir) {
        name = path.basename(filePath).replace(".services", "")
        var tmpPath = path.join(filePath, "init.lua")
        rbxPath = _robloxPathDict.getRbxPath(filePath)
        filePath = tmpPath
    } else {
        rbxPath = _robloxPathDict.getRbxPath(filePath)
        name = path.basename(filePath).replace(".services.lua", "")
    }


    filePath = filePath.replace(/\\/g, '/');
    const fileContent = fs.readFileSync(filePath, 'utf8');
    const lines = fileContent.split('\n');

    var comment = ""

    for (const line of lines) {
        if (line.match(/return function\([a-zA-Z_][a-zA-Z0-9_]*:\s*IServiceCollection/)) {
            var handler = line.replace("return function(", "").replace(" end", "").trim().slice(0, -1)
            serviceCollectionExtensions[rbxPath] = {
                FilePath: filePath,
                Handler: handler,
                Name: name,
                Comment: comment
            };
            return true;
        }
        comment += line
    }

    // get full path
    const fullPath = path.resolve(filePath);

    throw new Error(`扩展服务模块 (*.services.lua) 代码中必须包含 'return function({name}: IServiceCollection', 文件地址: ${fullPath}`)
}


function tryGenModuleFolder(folderPath) {
    var changed = false
    for (const file of fs.readdirSync(folderPath)) {
        const fullPath = path.join(folderPath, file);
        if (fs.statSync(fullPath).isFile() && file.endsWith('.lua') && !file.endsWith('.services.lua')) {
            changed = changed | genModule(fullPath)
        }
    }
    return changed
}

function isServiceFile(filePath) {
    if (fs.statSync(filePath).isDirectory() && filePath.endsWith('.services')) {
        if (fs.existsSync(path.join(filePath, "init.lua"))) {
            return true
        }
    }

    return filePath.endsWith('.services.lua') && filePath != ".services.lua"
}

// 尝试生成路径, 如果有变更, 返回true
function tryGen(filePath, recursive = false) {

    var changed = false
    if (!fs.existsSync(filePath)) {
        return false
    }
    if (fs.statSync(filePath).isFile()) {

    } else {
        const files = fs.readdirSync(filePath);
        var genModuleFolder = recursive
        for (const file of files) {

            const fullPath = path.join(filePath, file);

            if (isServiceFile(fullPath)) {
                genModuleFolder = true
            } else {
                changed = changed | tryGen(fullPath, true)
            }
            if (genModuleFolder) {
                changed = changed | tryGenModuleFolder(filePath)
                changed = changed | tryGenHostBuilderExtension(fullPath)
            }
        }
    }

    return changed
}

function findAndGenSubfolders(basePath, events) {
    if (_options.isIgnoreFolder(path.resolve(basePath))) return
    var changed = false

    if (!fs.existsSync(basePath)) {
        changed = true
        return false
    }

    // is dir
    if (!fs.lstatSync(basePath).isDirectory()) {
        // parent
        basePath = path.dirname(basePath)
    }

    changed |= tryGen(basePath, events)

    return changed
}

module.exports = {
    Init: function (options) {
        _options = options
        _robloxPathDict = options.robloxPathDict;
    },

    TryGen: function (paths) {
        var changed = false
        for (const basePath of paths) {
            changed |= findAndGenSubfolders(basePath);
        }
        return changed
    },
    TryGenOnUpdate: function (events) {
        var changed = false

        for (var key in events) {
            basePath = path.dirname(key);
            if (fs.existsSync(basePath)) {
                changed |= findAndGenSubfolders(basePath, events)
            }
        }

        return changed
    },
    GetLuaTypes: function () {
        return luaTypes
    }
    ,
    GetServiceCollectionExtensions: function () {
        return serviceCollectionExtensions
    }
}